document.addEventListener('DOMContentLoaded',()=>{const importForm=document.getElementById('import-fetch-form');if (importForm){importForm.addEventListener('submit',async(e)=>{e.preventDefault();const submitBtn=document.getElementById('import-submit-btn');const urlInput=document.getElementById('import-url');const loadingState=document.getElementById('import-loading-state');const successState=document.getElementById('import-success-state');const errorState=document.getElementById('import-error-state');const proceedBtn=document.getElementById('import-proceed-btn');loadingState.style.display='block';successState.style.display='none';errorState.style.display='none';submitBtn.disabled=true;const formData=new FormData(importForm);try{const response=await fetch('/dashboard/import/fetch/',{method:'POST',body:formData,headers:{'X-Requested-With':'XMLHttpRequest'}});const data=await response.json();if (response.ok&&data.success){sessionStorage.setItem('sg_import_data',JSON.stringify(data.mapped_data));loadingState.style.display='none';successState.style.display='block';const warningsContainer=document.getElementById('import-success-warnings');warningsContainer.innerHTML='';const warnings=data.mapped_data.image_warnings||[];if (warnings.length>0){warnings.forEach(warn=>{const li=document.createElement('div');li.className='text-amber-600 font-semibold';li.textContent=`⚠️ ${warn}`;warningsContainer.appendChild(li);});proceedBtn.style.display='inline-block';proceedBtn.onclick=()=>{window.location.href=data.redirect_url;};}else{setTimeout(()=>{window.location.href=data.redirect_url;},1500);}}else{loadingState.style.display='none';errorState.style.display='block';document.getElementById('import-error-message').textContent=data.error||'حدث خطأ غير متوقع أثناء جلب البيانات.';submitBtn.disabled=false;}}catch(err){loadingState.style.display='none';errorState.style.display='block';document.getElementById('import-error-message').textContent='تعذر الاتصال بخادم الاستيراد. يرجى التحقق من الشبكة.';submitBtn.disabled=false;}});}const importDataStr=sessionStorage.getItem('sg_import_data');if (importDataStr){try{const importData=JSON.parse(importDataStr);setTimeout(()=>{try{if (importData.form_initial)sg_fill_form(importData.form_initial);}catch(err){console.error('Error in sg_fill_form',err);}try{if (importData.confidence)sg_apply_confidence(importData.confidence);}catch(err){console.error('Error in sg_apply_confidence',err);}try{if (importData.image_paths)sg_fill_images(importData.image_paths);}catch(err){console.error('Error in sg_fill_images',err);}try{sg_fill_formsets(importData);}catch(err){console.error('Error in sg_fill_formsets',err);}try{sg_show_import_banner(importData.image_warnings);}catch(err){console.error('Error in sg_show_import_banner',err);}setTimeout(()=>{window.scrollTo({top:0,behavior:'instant'});document.documentElement.scrollTop=0;document.body.scrollTop=0;},150);sessionStorage.removeItem('sg_import_data');},300);}catch(e){console.error('Failed to parse import data',e);}}});function sg_fill_form(formInitial){for (const [key,value] of Object.entries(formInitial)){if (value===null||value===undefined)continue;const proEditorMount=document.querySelector(`.pro-editor-mount[data-field-name="${key}"]`);if (proEditorMount){const editorArea=proEditorMount.querySelector('.pro-editor-content');if (editorArea){editorArea.innerHTML=value;}const textarea=proEditorMount.querySelector('textarea');if (textarea){textarea.value=value;}continue;}const inputs=document.querySelectorAll(`[name="${key}"]`);if (inputs.length===0)continue;if (inputs[0].type==='checkbox'&&(Array.isArray(value)||inputs.length>1)){const valuesArray=Array.isArray(value)?value.map(String):[String(value)];inputs.forEach(cb=>{cb.checked=valuesArray.includes(cb.value);cb.dispatchEvent(new Event('input',{bubbles:true}));cb.dispatchEvent(new Event('change',{bubbles:true}));});continue;}const input=inputs[0];const simpleEditorSibling=input.previousElementSibling;if (simpleEditorSibling&&simpleEditorSibling.classList.contains('rich-text-toolbar')){const contenteditable=simpleEditorSibling.nextElementSibling;if (contenteditable&&contenteditable.hasAttribute('contenteditable')){contenteditable.innerHTML=value;input.value=value;continue;}}if (input.type==='checkbox'){input.checked=!!value;}else{input.value=value;}input.dispatchEvent(new Event('input',{bubbles:true}));input.dispatchEvent(new Event('change',{bubbles:true}));}}function sg_apply_confidence(confidenceMap){for (const [key,rating] of Object.entries(confidenceMap)){let el=document.querySelector(`[name="${key}"]`);if (!el)continue;const proEditorMount=el.closest('.pro-editor-mount');if (proEditorMount){el=proEditorMount;}else{const editorSibling=el.previousElementSibling;if (editorSibling&&editorSibling.classList.contains('rich-text-toolbar')){const contenteditable=editorSibling.nextElementSibling;if (contenteditable&&contenteditable.hasAttribute('contenteditable')){el=contenteditable;}}}el.classList.remove('import-confidence-high','import-confidence-medium','import-confidence-none');if (rating==='high'){el.classList.add('import-confidence-high');}else if (rating==='medium'){el.classList.add('import-confidence-medium');}else if (rating==='none'){el.classList.add('import-confidence-none');}}}function sg_fill_images(imagePaths){const form=document.querySelector('form');if (!form)return;for (const [imgType,imgUrl] of Object.entries(imagePaths)){if (!imgUrl)continue;let fieldName='main_image';if (imgType==='logo'){fieldName='logo';}else if (imgType==='og_image'){fieldName='og_image';}else if (imgType==='main_image'||imgType==='featured_image'){if (document.querySelector('[name="featured_image"]')){fieldName='featured_image';}else{fieldName='main_image';}}const input=document.querySelector(`[name="${fieldName}"]`);if (!input)continue;const hiddenInputName=`imported_${fieldName}_path`;let hiddenInput=form.querySelector(`input[name="${hiddenInputName}"]`);if (!hiddenInput){hiddenInput=document.createElement('input');hiddenInput.type='hidden';hiddenInput.name=hiddenInputName;form.appendChild(hiddenInput);}hiddenInput.value=imgUrl;const uploadZone=document.getElementById(`upload-zone-${input.id}`);if (uploadZone){const previewDiv=uploadZone.querySelector('.image-upload-preview');const placeholderDiv=uploadZone.querySelector('.image-upload-placeholder');const filenameDiv=uploadZone.querySelector('.image-upload-filename');if (previewDiv&&placeholderDiv){const img=previewDiv.querySelector('img');if (img)img.src=imgUrl;previewDiv.style.display='block';placeholderDiv.style.display='none';if (filenameDiv){const filenameP=filenameDiv.querySelector('p');if (filenameP)filenameP.textContent='تم استيراد الصورة بنجاح';filenameDiv.style.display='block';}}}}}function sg_import_faculty_programs(facultyItem,programs){const fpm=window.facultyProgramsManager;if (!fpm)return;const facultyIndex=facultyItem.getAttribute('data-faculty-index');const programsContainer=facultyItem.querySelector('[data-programs-container]');const totalFormsInput=facultyItem.querySelector(`[name="faculty-${facultyIndex}-programs-TOTAL_FORMS"]`);if (programsContainer&&totalFormsInput){const existingRows=programsContainer.querySelectorAll('.fpm-program-row');existingRows.forEach(row=>{const idInput=row.querySelector('[name$="-id"]');const deleteInput=row.querySelector('[name$="-DELETE"]');if (idInput&&idInput.value){if (deleteInput)deleteInput.value='on';row.classList.add('fpm-program-row--deleted');row.style.opacity='0.3';row.style.pointerEvents='none';}else{row.remove();}});const remaining=programsContainer.querySelectorAll('.fpm-program-row:not(.fpm-program-row--deleted)');if (remaining.length===0&&!programsContainer.querySelector('.fpm-empty-row')){const emptyRow=document.createElement('tr');emptyRow.className='fpm-empty-row';emptyRow.innerHTML='<td colspan="4" class="fpm-empty-message">لا توجد برامج مضافة</td>';programsContainer.appendChild(emptyRow);}}const wrapper=facultyItem.querySelector('.faculty-item__programs-wrapper');if (wrapper){wrapper.style.display='block';}programs.forEach(program=>{fpm.addProgram(facultyItem);const container=facultyItem.querySelector('[data-programs-container]');const allRows=container.querySelectorAll('.fpm-program-row');const newRow=allRows[allRows.length-1];const nameField=newRow.querySelector('textarea[name$="-name"],input[name$="-name"]');const durationInput=newRow.querySelector('input[name$="-duration"]');const tuitionInput=newRow.querySelector('input[name$="-tuition_fees"]');if (nameField){nameField.value=program.name||'';if (nameField.tagName==='TEXTAREA'){fpm.autoResizeTextarea(nameField);}}if (durationInput)durationInput.value=program.duration||'';if (tuitionInput)tuitionInput.value=program.tuition_fees||'';});}function normalizeArabic(text){if (!text)return '';return text.toString().trim().replace(/[أإآ]/g,'ا').replace(/ة/g,'ه').replace(/ى/g,'ي').replace(/\s+/g,' ').toLowerCase();}function sg_fill_formsets(importData){if (window.facultyProgramsManager){let facultiesToImport=[];if (importData.faculties_raw_html){try{const parsed=window.facultyProgramsManager.parseElementorAccordion(importData.faculties_raw_html);if (parsed&&parsed.faculties&&parsed.faculties.length>0){facultiesToImport=parsed.faculties;}}catch(err){console.error('Error parsing faculties raw HTML',err);}}if (facultiesToImport.length===0&&importData.faculties_data){facultiesToImport=importData.faculties_data;}const existingFaculties=Array.from(window.facultyProgramsManager.container.querySelectorAll('.faculty-item'));const existingMap={};existingFaculties.forEach(item=>{const nameInput=item.querySelector('.faculty-item__input')||item.querySelector('input[name$="-name"]');if (nameInput){const name=normalizeArabic(nameInput.value);if (name){existingMap[name]=item;}}});console.log("Existing faculties Map keys:",Object.keys(existingMap));console.log("Faculties to import(normalized):",facultiesToImport.map(f=>normalizeArabic(f.name)));const reusedItems=new Set();facultiesToImport.forEach(faculty=>{try{const importedName=normalizeArabic(faculty.name);const existingItem=existingMap[importedName];if (existingItem){console.log(`Reusing faculty:${faculty.name}`);reusedItems.add(existingItem);const deleteInput=existingItem.querySelector('input[name$="-DELETE"]');if (deleteInput){deleteInput.value='';deleteInput.checked=false;}existingItem.style.opacity='1';existingItem.style.pointerEvents='auto';existingItem.classList.remove('faculty-item--deleted');existingItem.style.display='';sg_import_faculty_programs(existingItem,faculty.programs);}else{console.log(`Creating new faculty:${faculty.name}`);window.facultyProgramsManager.addFaculty();const allItems=window.facultyProgramsManager.container.querySelectorAll('.faculty-item');const newFacultyItem=allItems[allItems.length-1];const nameInput=newFacultyItem.querySelector('input[name$="-name"]');if (nameInput){nameInput.value=faculty.name;}sg_import_faculty_programs(newFacultyItem,faculty.programs);}}catch(err){console.error('Error importing faculty',err);}});existingFaculties.forEach(item=>{if (!reusedItems.has(item)){const deleteInput=item.querySelector('input[name$="-DELETE"]');if (deleteInput){deleteInput.value='on';deleteInput.checked=true;}item.style.opacity='0.5';item.style.pointerEvents='none';item.classList.add('faculty-item--deleted');}});try{window.facultyProgramsManager.closeAllFaculties();}catch(err){}try{window.facultyProgramsManager.updateState();window.facultyProgramsManager.updateSortOrders();}catch(err){}}if (window.faqManager){let faqsToImport=[];if (importData.faqs_raw_html){try{const parsed=window.faqManager.parseElementorAccordion(importData.faqs_raw_html);if (parsed&&parsed.faqs&&parsed.faqs.length>0){faqsToImport=parsed.faqs;}}catch(err){console.error('Error parsing FAQs raw HTML',err);}}if (faqsToImport.length===0&&importData.faqs_data){faqsToImport=importData.faqs_data;}const existingFaqs=Array.from(window.faqManager.container.querySelectorAll('.faq-item'));const existingMap={};existingFaqs.forEach(item=>{const questionInput=item.querySelector('input[name$="-question"]');if (questionInput){const question=normalizeArabic(questionInput.value);if (question){existingMap[question]=item;}}});const reusedFaqs=new Set();faqsToImport.forEach(faq=>{try{const importedQuestion=normalizeArabic(faq.question);const existingItem=existingMap[importedQuestion];if (existingItem){reusedFaqs.add(existingItem);const deleteInput=existingItem.querySelector('input[name$="-DELETE"]');if (deleteInput){deleteInput.value='';deleteInput.checked=false;}existingItem.style.opacity='1';existingItem.style.pointerEvents='auto';existingItem.classList.remove('faq-item--deleted');existingItem.style.display='';const answerInput=existingItem.querySelector('textarea[name$="-answer"]');if (answerInput){answerInput.value=faq.answer;}}else{window.faqManager.addFAQ();const allItems=window.faqManager.container.querySelectorAll('.faq-item');const newFAQItem=allItems[allItems.length-1];const questionInput=newFAQItem.querySelector('input[name$="-question"]');const answerInput=newFAQItem.querySelector('textarea[name$="-answer"]');if (questionInput){questionInput.value=faq.question;window.faqManager.updateQuestionPreview(newFAQItem);}if (answerInput){answerInput.value=faq.answer;}}}catch(err){console.error('Error importing FAQ',err);}});existingFaqs.forEach(item=>{if (!reusedFaqs.has(item)){const deleteInput=item.querySelector('input[name$="-DELETE"]');if (deleteInput){deleteInput.value='on';deleteInput.checked=true;}item.style.opacity='0.5';item.style.pointerEvents='none';item.classList.add('faq-item--deleted');}});try{window.faqManager.updateState();}catch(err){}}if (importData.subjects_tables&&importData.subjects_tables.length>0){sg_clear_django_formset('subjects_tables');sg_fill_django_formset('subjects_tables',importData.subjects_tables,{'key':'academic_year','value':'subjects'});}if (importData.salary_tables&&importData.salary_tables.length>0){sg_clear_django_formset('salary_tables');sg_fill_django_formset('salary_tables',importData.salary_tables,{'key':'job_title','value':'average_monthly_salary'});}if (importData.countries_tables&&importData.countries_tables.length>0){sg_clear_django_formset('countries_tables');sg_fill_django_formset('countries_tables',importData.countries_tables,{'key':'destination','value':'annual_fees'});}}function sg_clear_django_formset(prefix){if (!window.formsetManagers)return;const manager=window.formsetManagers[prefix];if (!manager)return;const deleteCheckboxes=manager.formsetContainer.querySelectorAll('input[name$="-DELETE"]');deleteCheckboxes.forEach(cb=>{cb.checked=true;cb.dispatchEvent(new Event('change',{bubbles:true}));});}function sg_fill_django_formset(prefix,dataArray,fieldMap){if (!window.formsetManagers)return;const manager=window.formsetManagers[prefix];if (!manager)return;dataArray.forEach((item,index)=>{if (index>0){manager.addForm();}for (const [wpKey,djangoField] of Object.entries(fieldMap)){const inputName=`${prefix}-${index}-${djangoField}`;const input=manager.formsetContainer.querySelector(`[name="${inputName}"]`);if (input){input.value=item[wpKey]||'';input.dispatchEvent(new Event('input',{bubbles:true}));}}});}function sg_show_import_banner(warnings){let banner=document.getElementById('import-banner');if (!banner){const formContainer=document.querySelector('form');if (!formContainer)return;banner=document.createElement('div');banner.id='import-banner';banner.className='import-banner';banner.innerHTML=`<svg style="width:24px;height:24px;color:var (--warning);flex-shrink:0;" fill="none" stroke="currentColor" viewBox="0 0 24 24" stroke-width="2"><path stroke-linecap="round" stroke-linejoin="round" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"></path></svg><div style="flex:1;"><strong style="color:var (--text-primary);">تم ملء هذا الفورم تلقائياً من نظام الاستيراد.</strong><p style="font-size:13px;color:var (--text-secondary);margin-top:4px;">يرجى مراجعة الحقول المميزة بالأصفر(ثقة متوسطة)والأحمر(حاجة للمراجعة أو الإدخال اليدوي).</p><div id="import-banner-warnings" style="margin-top:8px;font-size:12px;color:var (--danger);line-height:1.5;"></div></div><button type="button" onclick="document.getElementById('import-banner').remove()" style="background:none;border:none;cursor:pointer;color:var (--text-muted);font-size:16px;">✕</button>`;formContainer.parentNode.insertBefore(banner,formContainer);}const warningsDiv=document.getElementById('import-banner-warnings');if (warningsDiv&&warnings&&warnings.length>0){warnings.forEach(warn=>{const p=document.createElement('p');p.textContent=`⚠️ ${warn}`;warningsDiv.appendChild(p);});}let legend=document.getElementById('confidence-legend');if (!legend){legend=document.createElement('div');legend.id='confidence-legend';legend.className='confidence-legend';legend.innerHTML=`<span class="legend-high">● ثقة عالية</span><span class="legend-medium">● بحاجة لمراجعة</span><span class="legend-none">● إدخال يدوي</span>`;banner.querySelector('div').appendChild(legend);}}